window.docContents[121].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--String-and-regex":{"contents":"#eval Env.runIO do\n  let solver ← Solver.new\n  solver.setOption \"produce-models\" \"true\"\n  let zero ← smt! 0\n  let aString ← smt! \"cvc.lean\"\n\n  let s1 ← Term.mkSymbolAs String \"s1\"\n  let s1Len ← s1.strLength\n  smt! s1Len = 11 >>= solver.assert\n  let s1Char0 ← s1.strCharAt zero\n  smt! s1Char0 = \"!\" >>= solver.assert\n\n  solver.assert (← s1.strContains aString)\n  solver.checkSat (ifSat := do\n    let s1 ← solver.getValue s1\n    println! \"s1 : `{s1}`\"\n  )\n  let regex1 ← regex! . \"cvc\" .* ['0'-'9']{2}\n  s1.strInRegex regex1 >>= solver.assert\n  solver.checkSat\n    (ifSat := do\n      let s1 ← solver.getValue s1\n      println! \"s1 : `{s1}`\")\n  let regex1 ← regex! . \"cvc\" .* ['0'-'9']{3}\n  s1.strInRegex regex1 >>= solver.assert\n  solver.checkSat\n    (ifUnsat := println! \"unsat\")\n\n\ns1 : `!AAcvc.lean`\ns1 : `!cvc.lean00`\nunsat\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.5. String and regex","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--String-and-regex"}});